// Interface texts in the language of the user.
//
// Every text is written in the code the way the Qt interface wrote it: the
// Qt context ("caruspex::FaultsPage") and the German source. t() looks up
// "context|german" in the catalog generated by scripts/gen-i18n.mjs from the
// shared translations, so every existing translation applies unchanged.
//
//   t("caruspex::MainWindow", "Verbinde mit %1:%2 ...", host, port)
//   tn("caruspex::MainWindow", "%n Anschluss/Anschlüsse gefunden.", ports)
//
// %1 to %9 are replaced the way QString::arg() does; %n takes the count and
// picks the plural form in the order Qt uses for the language. German shows
// the source itself. A text missing in a catalog shows in English, the way
// the Rust core falls back.

import languageCodes from "./generated/languages.json";

export interface LanguageInfo {
  code: string;
  nativeName: string;
  rightToLeft: boolean;
}

// Same order and names as core/Lang.cpp, so the settings list matches.
export const LANGUAGES: readonly LanguageInfo[] = [
  { code: "de", nativeName: "Deutsch", rightToLeft: false },
  { code: "en", nativeName: "English", rightToLeft: false },
  { code: "es", nativeName: "Español", rightToLeft: false },
  { code: "fr", nativeName: "Français", rightToLeft: false },
  { code: "pt", nativeName: "Português", rightToLeft: false },
  { code: "it", nativeName: "Italiano", rightToLeft: false },
  { code: "nl", nativeName: "Nederlands", rightToLeft: false },
  { code: "pl", nativeName: "Polski", rightToLeft: false },
  { code: "cs", nativeName: "Čeština", rightToLeft: false },
  { code: "ru", nativeName: "Русский", rightToLeft: false },
  { code: "uk", nativeName: "Українська", rightToLeft: false },
  { code: "tr", nativeName: "Türkçe", rightToLeft: false },
  { code: "ar", nativeName: "العربية", rightToLeft: true },
  { code: "zh", nativeName: "中文", rightToLeft: false },
  { code: "ja", nativeName: "日本語", rightToLeft: false },
  { code: "ko", nativeName: "한국어", rightToLeft: false },
  { code: "hi", nativeName: "हिन्दी", rightToLeft: false },
  { code: "id", nativeName: "Bahasa Indonesia", rightToLeft: false },
];

type Entry = string | string[];
type Catalog = Record<string, Entry>;

const loaders = import.meta.glob<{ default: Catalog }>([
  "./generated/*.json",
  "!./generated/languages.json",
  "!./generated/core-*.json",
]);

let active = "de";
let catalog: Catalog = {};
let english: Catalog = {};
let plurals = new Intl.PluralRules("de");

export function language(): string {
  return active;
}

export function isRightToLeft(code: string = active): boolean {
  return LANGUAGES.find((l) => l.code === code)?.rightToLeft ?? false;
}

// Locale for Intl formatting of numbers and dates.
export function locale(): string {
  return active;
}

// Resolves "auto" against the system language, like effectiveLanguage() in
// Settings.cpp: the system language when Caruspex has it, English otherwise.
export function effectiveLanguage(setting: string): string {
  if ((languageCodes as string[]).includes(setting)) return setting;
  const system = (typeof navigator !== "undefined" ? navigator.language : "en").toLowerCase();
  const base = system.split(/[-_]/)[0] ?? "en";
  return (languageCodes as string[]).includes(base) ? base : "en";
}

async function load(code: string): Promise<Catalog> {
  const loader = loaders[`./generated/${code}.json`];
  if (!loader) return {};
  return (await loader()).default;
}

// Loads the catalog of a language and makes it the active one.
export async function setLanguage(code: string): Promise<void> {
  if (Object.keys(english).length === 0) english = await load("en");
  catalog = code === "de" ? {} : code === "en" ? english : await load(code);
  active = code;
  plurals = new Intl.PluralRules(code);
  if (typeof document !== "undefined") {
    document.documentElement.lang = code;
    document.documentElement.dir = isRightToLeft(code) ? "rtl" : "ltr";
  }
}

// Index of the plural form, in the order Qt keeps the forms per language
// (see TRANSLATING.md): 1 form for zh, ja, ko, id; 2 (one, other) for most;
// 3 (one, few, many) for pl, cs, ru, uk; 6 (zero, one, two, few, many,
// other) for ar.
function pluralIndex(n: number, forms: number): number {
  if (forms <= 1) return 0;
  const category = plurals.select(n);
  if (forms === 6) {
    const order = ["zero", "one", "two", "few", "many", "other"];
    const i = order.indexOf(category);
    return i < 0 ? 5 : i;
  }
  if (forms === 3) {
    if (category === "one") return 0;
    if (category === "few") return 1;
    return 2;
  }
  return category === "one" ? 0 : 1;
}

// QString::arg(): each argument replaces the lowest numbered %N still in the
// text.
function applyArgs(text: string, args: readonly unknown[]): string {
  let out = text;
  for (const arg of args) {
    let lowest = 100;
    const re = /%(\d{1,2})/g;
    let m: RegExpExecArray | null;
    while ((m = re.exec(out)) !== null) {
      const n = Number(m[1]);
      if (n >= 1 && n < lowest) lowest = n;
    }
    if (lowest === 100) break;
    const value = String(arg);
    out = out.replace(new RegExp(`%${lowest}(?!\\d)`, "g"), () => value);
  }
  return out;
}

const reported = new Set<string>();

function lookup(context: string, de: string): Entry | undefined {
  const key = `${context}|${de}`;
  const hit = catalog[key] ?? (active === "de" ? undefined : english[key]);
  if (import.meta.env.DEV && english[key] === undefined && Object.keys(english).length > 0 && !reported.has(key)) {
    reported.add(key);
    console.warn(`[i18n] text without translation, add it to new-texts.json: ${key}`);
  }
  return hit;
}

function pick(entry: Entry | undefined, de: string, n: number | null): string {
  if (entry === undefined) return de;
  if (typeof entry === "string") return entry;
  if (entry.length === 0) return de;
  const i = n === null ? entry.length - 1 : pluralIndex(n, entry.length);
  return entry[Math.min(i, entry.length - 1)] ?? de;
}

// A text, with %1 ... %9 filled from args.
export function t(context: string, de: string, ...args: unknown[]): string {
  return applyArgs(pick(lookup(context, de), de, null), args);
}

// A text with a count: %n becomes n (and picks the plural form), %1 ... %9
// are filled from args.
export function tn(context: string, de: string, n: number, ...args: unknown[]): string {
  const form = pick(lookup(context, de), de, n);
  return applyArgs(form.replace(/%n/g, String(n)), args);
}

// A translator bound to one context, for pages with many texts:
//   const tr = translator("caruspex::FaultsPage");
//   tr("Fehler lesen"); tr.n("%n Einträge", rows.length)
export interface Translator {
  (de: string, ...args: unknown[]): string;
  n(de: string, n: number, ...args: unknown[]): string;
}

export function translator(context: string): Translator {
  const fn = ((de: string, ...args: unknown[]) => t(context, de, ...args)) as Translator;
  fn.n = (de: string, n: number, ...args: unknown[]) => tn(context, de, n, ...args);
  return fn;
}

// Numbers the way QLocale writes them in the active language ("48.213" in
// German), with a fixed number of decimals.
export function localeNumber(value: number, decimals = 0): string {
  return new Intl.NumberFormat(active, {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals,
  }).format(value);
}

// Numbers the way QString::number(value, 'f', decimals) writes them: a dot,
// no grouping.
export function fixed(value: number, decimals = 0): string {
  return value.toFixed(decimals);
}

// Date and time in the active language.
export function localeDate(value: Date | string | number, options?: Intl.DateTimeFormatOptions): string {
  const d = value instanceof Date ? value : new Date(value);
  return new Intl.DateTimeFormat(active, options ?? { dateStyle: "medium" }).format(d);
}

export function localeDateTime(value: Date | string | number): string {
  const d = value instanceof Date ? value : new Date(value);
  return new Intl.DateTimeFormat(active, { dateStyle: "medium", timeStyle: "short" }).format(d);
}
